(() => {
  const ID = 'tile-trio';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, board, slots, hint, scoreEl, movesEl, tiles = [], picked = [], score = 0, moves = 0, callbacks = {}, initialized = false, finished = false;
  const SYMBOLS = ['◆','●','▲','✦'];
  const $ = id => document.getElementById(id);
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function reset() { tiles = [...SYMBOLS, ...SYMBOLS, ...SYMBOLS].sort(() => Math.random() - .5).map((symbol, index) => ({ id: index, symbol, used: false })); picked = []; score = 0; moves = 0; finished = false; render(); }
  function render() { board.innerHTML = tiles.filter(tile => !tile.used).map(tile => `<button type="button" class="trio-tile ${picked.includes(tile.id) ? 'is-picked' : ''}" data-trio-tile="${tile.id}" aria-label="Фигура ${tile.symbol}">${tile.symbol}</button>`).join(''); slots.innerHTML = picked.map(id => `<span class="trio-slot">${tiles.find(tile => tile.id === id).symbol}</span>`).join(''); while (slots.children.length < 3) slots.insertAdjacentHTML('beforeend','<span class="trio-slot">·</span>'); scoreEl.textContent = score; movesEl.textContent = moves; }
  function pick(id) { if (finished) return; if (picked.includes(id)) picked = picked.filter(value => value !== id); else if (picked.length < 3) picked.push(id); render(); if (picked.length === 3) setTimeout(check, 220); }
  function check() { if (picked.length !== 3) return; moves += 1; const selected = picked.map(id => tiles.find(tile => tile.id === id)); if (selected.every(tile => tile.symbol === selected[0].symbol)) { selected.forEach(tile => { tile.used = true; }); score += 100 + Math.max(0, 30 - moves * 2); hint.textContent = 'Тройка собрана!'; haptic('medium'); } else { score = Math.max(0, score - 20); hint.textContent = 'Нужны три одинаковые стадии.'; haptic('heavy'); } picked = []; render(); if (tiles.every(tile => tile.used)) finish(); }
  function finish() { finished = true; const previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestMoves: previous.bestMoves ? Math.min(previous.bestMoves, moves) : moves, lastResult: { score, moves } }), reward = Math.max(1, Math.floor(score / 130)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, moves } }); shell().emit('tile_trio_finished', { gameId: ID, score, moves, reward }); shell().emit('game_finished', { gameId: ID, score, reward, moves, victory: true }); shell().ResultScreen.show(screen.querySelector('[data-trio-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: 'Три стадии<br>собраны!', details: { moves, trios: '4 / 4' } }); screen.querySelector('[data-trio-result]').hidden = false; }
  function start() { reset(); screen.querySelector('[data-trio-start]').hidden = true; screen.querySelector('[data-trio-result]').hidden = true; shell().emit('tile_trio_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-trio-start]').hidden = false; screen.querySelector('[data-trio-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-trio-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); reset(); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function init() { if (initialized) return; initialized = true; screen = $('tileTrioScreen'); screen.innerHTML = `<div class="tile-trio-inner"><header class="tile-trio-hud"><button class="icon-button" data-trio-close aria-label="На главную">×</button><div class="tile-trio-brand"><small>TELEPLAY · ПАЗЛЫ</small><b>Tile Trio</b></div><div class="tile-trio-stat"><small>ХОДЫ</small><b data-trio-moves>0</b></div><button class="icon-button" data-trio-reset aria-label="Начать заново">↻</button></header><div class="tile-trio-board" data-trio-board></div><div class="tile-trio-slot" data-trio-slots></div><p class="tile-trio-hint" data-trio-hint>Собери три одинаковые стадии</p></div><div class="start-panel" data-trio-start><span class="panel-kicker">TELEPLAY · ПАЗЛЫ</span><h2>Tile<br>Trio</h2><p>Выбирай три одинаковые плитки.<br>Собери все стадии процесса.</p><button class="play-button large" data-trio-start-button>Начать сбор</button><div class="record">Лучший результат: <b data-trio-menu-best>0</b></div></div><div class="start-panel result-panel" data-trio-result hidden><span class="panel-kicker" data-result="kicker">ПОЛЕ ОЧИЩЕНО</span><h2 data-result="title">Три стадии<br>собраны!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Ходы <b data-result="moves">0</b></span><span>Тройки <b data-result="trios">0 / 4</b></span></div><button class="play-button large" data-trio-replay>Новая партия</button><button class="text-button" data-trio-home>На главную</button></div>`; board = screen.querySelector('[data-trio-board]'); slots = screen.querySelector('[data-trio-slots]'); hint = screen.querySelector('[data-trio-hint]'); scoreEl = screen.querySelector('[data-result="score"]'); movesEl = screen.querySelector('[data-trio-moves]'); board.addEventListener('click', event => { const tile = event.target.closest('[data-trio-tile]'); if (tile) pick(Number(tile.dataset.trioTile)); }); screen.querySelector('[data-trio-start-button]').addEventListener('click', start); screen.querySelector('[data-trio-replay]').addEventListener('click', start); screen.querySelector('[data-trio-home]').addEventListener('click', close); screen.querySelector('[data-trio-close]').addEventListener('click', close); screen.querySelector('[data-trio-reset]').addEventListener('click', reset); reset(); }
  window.TileTrioGame = { init, open, hide, close, start, restart: start, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
